CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE tenants (id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Kolkata', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (tenant_id uuid REFERENCES tenants(id), user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','trader','strategy_author','risk_approver','analyst','support')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE instruments (id text PRIMARY KEY, symbol text NOT NULL, source text NOT NULL, synthetic boolean NOT NULL DEFAULT true);
CREATE TABLE strategies (tenant_id uuid REFERENCES tenants(id), id uuid NOT NULL, name text NOT NULL, version integer NOT NULL, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id));
CREATE TABLE orders (tenant_id uuid REFERENCES tenants(id), id uuid NOT NULL, idempotency_key text NOT NULL, instrument_id text REFERENCES instruments(id), side text NOT NULL CHECK(side IN ('BUY','SELL')), quantity integer NOT NULL CHECK(quantity>0), limit_price numeric(20,4) NOT NULL CHECK(limit_price>0), state text NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE order_events (tenant_id uuid NOT NULL, id uuid NOT NULL, order_id uuid NOT NULL, state text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE risk_decisions (tenant_id uuid NOT NULL, id uuid NOT NULL, order_id uuid NOT NULL, allowed boolean NOT NULL, reasons jsonb NOT NULL, policy_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE audit_events (tenant_id uuid REFERENCES tenants(id), id uuid NOT NULL, actor_id uuid, action text NOT NULL, payload jsonb NOT NULL, previous_hash text NOT NULL, hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id));
CREATE TABLE candles (instrument_id text REFERENCES instruments(id), source text NOT NULL, timestamp timestamptz NOT NULL, timeframe text NOT NULL, open numeric(20,4) NOT NULL, high numeric(20,4) NOT NULL, low numeric(20,4) NOT NULL, close numeric(20,4) NOT NULL, volume bigint NOT NULL, PRIMARY KEY(instrument_id,source,timestamp,timeframe)) PARTITION BY RANGE(timestamp);
CREATE TABLE candles_default PARTITION OF candles DEFAULT;
CREATE TABLE document_chunks (tenant_id uuid REFERENCES tenants(id), id uuid NOT NULL, source text NOT NULL, body text NOT NULL, embedding vector(768), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id));
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['memberships','strategies','orders','order_events','risk_decisions','audit_events','document_chunks'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tbl); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tbl); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'', true), '''')::uuid)',tbl); END LOOP; END $$;
CREATE INDEX orders_tenant_created ON orders(tenant_id,created_at DESC);
CREATE INDEX audit_tenant_created ON audit_events(tenant_id,created_at DESC);
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER risk_append_only BEFORE UPDATE OR DELETE ON risk_decisions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
